from(bucket: "energy")
    |> range(
        start: v.timeRangeStart,
        stop: v.timeRangeStop
    )
    |> filter(fn: (r) =>
        r._measurement == "pv_inverter"
    )
    |> filter(fn: (r) =>
        r._field == "ac_power_kw"
    )
    |> filter(fn: (r) =>
        r.device == "fronius_primo_4_0_1"
    )
    |> last()

